function JourneyPage() {
  const navigate = useNavigate();
  const { moods = [], topicLabel, professionalId, durationIndex, confirmed } = useBooking();
  const [generated, setGenerated] = useState(false);
  const [feedback, setFeedback] = useState("");
  const p = professionals.find(x => x.id === professionalId) || professionals[0];
  const duration = demoDurations[durationIndex];
  const rows = [["Como eu estava", moods.length ? moods.join(" · ") : "Não informado"], ["Sobre o que escolhi conversar", topicLabel || "Não escolhido"], ["Profissional", `${p.name} · perfil demonstrativo`], ["Duração", confirmed ? confirmed.duration : duration.label], ["Data", confirmed ? `${confirmed.day} · ${confirmed.time}` : "Demonstrativa"], ["Próximo passo", "Definido durante a conversa"]];
  const asText = () => `MINHA JORNADA — ACOLHE (protótipo educacional)\n\n${rows.map(([k, v]) => `${k}: ${v}`).join("\n")}\n\nEste resumo é demonstrativo e não é um documento clínico.\n`;
  const save = () => { const blob = new Blob([asText()], { type: "text/plain;charset=utf-8" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = "minha-jornada-acolhe.txt"; a.click(); URL.revokeObjectURL(url); setFeedback("Resumo salvo no seu dispositivo."); };
  const share = async () => { try { await navigator.clipboard.writeText(asText()); setFeedback("Resumo copiado — o compartilhamento é simulado neste protótipo."); } catch (e) { setFeedback("Compartilhamento simulado: copie o resumo manualmente."); } };
  const saveImage = async () => { setFeedback("Gerando o cartão da sua jornada..."); await downloadJourneyCard(rows); setFeedback("Cartão da jornada salvo como imagem."); toast.success("Cartão salvo.", { description: "minha-jornada-acolhe.png" }); };
  return <AppShell><main className="app-main journey-main"><div className="flow-heading"><span className="section-kicker">Depois da conversa</span><h1>Minha <em>jornada.</em></h1><p>Um resumo visual do caminho que você percorreu nesta demonstração.</p></div><section className="journey-timeline" data-testid="journey-timeline"><div className="journey-timeline-head"><span className="section-kicker">Seu percurso</span><span className="demo-label">DEMONSTRATIVO</span></div><JourneyFlow progress={confirmed ? 5 : professionalId ? 3 : topicLabel ? 2 : moods.length ? 1 : 0}/></section>
    {!generated
      ? <div className="journey-empty" data-testid="journey-empty"><FileText size={26}/><h2>Gere um resumo da sua jornada.</h2><p>Ele reúne apenas o que você escolheu aqui. Nada é enviado para nenhum servidor.</p><button className="button primary" onClick={() => setGenerated(true)} data-testid="generate-summary-button">Gerar resumo <ArrowRight size={16}/></button></div>
      : <><article className="journey-doc" data-testid="journey-summary"><div className="journey-doc-top"><span className="journey-doc-brand">acolhe<span className="window-mark"><BrandMark size={13}/></span></span><span className="demo-label">RESUMO DEMONSTRATIVO</span></div><h2>Minha jornada</h2><dl>{rows.map(([k, v]) => <div key={k}><dt>{k}</dt><dd data-testid={`journey-${k.split(" ")[0].toLowerCase()}`}>{v}</dd></div>)}</dl><p className="journey-doc-note">Este resumo não é um documento clínico e não substitui orientação profissional.</p></article><div className="journey-actions"><button className="button primary" onClick={saveImage} data-testid="download-image-button"><ImageIcon size={16}/> Baixar cartão</button><button className="button secondary" onClick={save} data-testid="save-summary-button"><Download size={16}/> Salvar em texto</button><button className="button secondary" onClick={share} data-testid="share-summary-button"><Share2 size={16}/> Compartilhar</button><button className="button quiet" onClick={() => navigate("/app/agenda")} data-testid="journey-agenda-button">Ir para a agenda</button></div>{feedback && <p className="journey-feedback" data-testid="journey-feedback">{feedback}</p>}</>}
    <button className="back-link" onClick={() => navigate("/app")} data-testid="journey-back-button"><ChevronLeft size={16}/> Voltar ao início</button></main></AppShell>;
}

function ResourcesPage() {
  const [open, setOpen] = useState(resources[0].id);
  return <MarketingLayout><main className="info-page"><section className="info-hero section"><div className="section-kicker">Recursos</div><h1 data-testid="resources-title">Conteúdo para pensar <em>sem pressa.</em></h1><p className="hero-lead">Textos curtos e educativos sobre assuntos que aparecem com frequência na vida escolar. Não são orientações clínicas nem diagnósticos.</p></section><section className="section resources-section"><div className="resource-grid">{resources.map(r => <article className={open === r.id ? "resource-card open" : "resource-card"} key={r.id} data-testid={`resource-${r.id}`}><button onClick={() => setOpen(open === r.id ? null : r.id)} data-testid={`resource-toggle-${r.id}`}><div><span className="resource-tag">{r.tag}</span><h2>{r.title}</h2></div><ChevronDown size={18}/></button>{open === r.id && <p data-testid={`resource-text-${r.id}`}>{r.text}</p>}</article>)}</div><p className="disclaimer-inline">Conteúdo educativo escrito para este protótipo. Não substitui orientação profissional.</p></section></main></MarketingLayout>;
}

function TermsPage() {
  const blocks = [["Natureza do projeto", "O Acolhe é um protótipo educacional. Não existe atendimento psicológico, pagamento, cadastro real ou vínculo profissional."], ["Uso demonstrativo", "Profissionais, horários, valores e conversas exibidos são fictícios e identificados como demonstrativos."], ["Não é emergência", "O Acolhe não é serviço de emergência e não deve ser usado em situações de risco imediato."], ["Seus dados", "Nenhum dado pessoal é enviado a servidores. As escolhas feitas aqui ficam apenas no seu navegador e podem ser apagadas limpando os dados do site."], ["Conteúdo", "Os textos educativos foram escritos para este protótipo e não representam pesquisa clínica nem estatísticas."], ["Mudanças", "Sendo um protótipo em evolução, telas, textos e funcionalidades podem mudar sem aviso."]];
  return <MarketingLayout><main className="info-page"><section className="info-hero section"><div className="section-kicker">Termos do protótipo</div><h1 data-testid="terms-title">Regras simples, em <em>linguagem clara.</em></h1><p className="hero-lead">Esta é a primeira camada: o essencial para entender o que este projeto é — e o que ele não é.</p></section><section className="section privacy-band"><div className="privacy-grid">{blocks.map(([t, d]) => <article className="privacy-card" key={t}><FileText size={18}/><div><h3>{t}</h3><p>{d}</p></div></article>)}</div></section></main></MarketingLayout>;
}

function InstitutionDashboard() {
  return <MarketingLayout><main className="info-page"><section className="info-hero section"><span className="status-chip" data-testid="institution-demo-chip">Exemplo demonstrativo · números fictícios</span><div className="section-kicker">Painel institucional</div><h1 data-testid="institution-dashboard-title">Indicadores agregados, <em>nunca individuais.</em></h1><p className="hero-lead">Uma demonstração de como uma instituição poderia acompanhar o uso do Acolhe sem acessar nenhuma informação pessoal ou clínica de estudantes.</p><Link to="/instituicoes" className="text-link" data-testid="dashboard-back-institution">Voltar para a proposta institucional <ArrowRight size={15}/></Link></section><InstitutionDashboardPanels/><InstitutionStrip compact={true}/></main></MarketingLayout>;
}

function NavigateToLogin({ next = "/app" }) { return <Navigate to={`/login?next=${next}`} replace/>; }
function AppRoutes() { useScrollReveal(); const location = useLocation(); return <div className="route-fade" key={location.pathname}><Routes><Route path="/" element={<Home/>}/><Route path="/login" element={<DemoLogin/>}/><Route path="/profissional-dashboard" element={<ProfessionalDashboard/>}/><Route path="/como-funciona" element={<InfoPage type="como-funciona"/>}/><Route path="/para-estudantes" element={<InfoPage type="para-estudantes"/>}/><Route path="/profissionais" element={<InfoPage type="profissionais"/>}/><Route path="/instituicoes" element={<InfoPage type="instituicoes"/>}/><Route path="/privacidade" element={<InfoPage type="privacidade"/>}/><Route path="/ajuda" element={<HelpPage/>}/><Route path="/preciso-ajuda" element={<EmergencyPage/>}/><Route path="/app" element={<AppHome/>}/><Route path="/app/assunto" element={<TopicPage/>}/><Route path="/app/profissionais" element={<ProfessionalsPage/>}/><Route path="/app/profissional/:id" element={<ProfilePage/>}/><Route path="/app/agendamento" element={<BookingPage/>}/><Route path="/app/pagamento" element={<PaymentPage/>}/><Route path="/app/confirmacao" element={<ConfirmationPage/>}/><Route path="/app/sessao" element={<SessionPage/>}/><Route path="/recursos" element={<ResourcesPage/>}/><Route path="/termos" element={<TermsPage/>}/><Route path="/instituicoes/painel" element={<InstitutionDashboard/>}/><Route path="/aluno" element={<Navigate to="/para-estudantes" replace/>}/><Route path="/profissional" element={<Navigate to="/profissionais" replace/>}/><Route path="/instituicao" element={<Navigate to="/instituicoes" replace/>}/><Route path="/app/agenda" element={<AgendaPage/>}/><Route path="/app/jornada" element={<JourneyPage/>}/><Route path="/app/pos-conversa" element={<PostConversation/>}/><Route path="*" element={<NotFoundPage/>}/></Routes></div>; }
export default function App() { useIntro(); useEffect(() => { document.title = "Acolhe — Um primeiro passo para cuidar de você"; const meta = document.querySelector('meta[name="description"]'); if (meta) meta.setAttribute("content", "Acolhe é uma proposta de plataforma que aproxima estudantes de profissionais de Psicologia de forma simples, acessível e virtual."); }, []); return <ThemeProvider><AuthProvider><BookingProvider><BrowserRouter><SkipLink/><AppRoutes/><CommandPalette/><Toaster position="bottom-right" gap={10} offset={26} toastOptions={{ className: "acolhe-toast", duration: 3200 }}/></BrowserRouter></BookingProvider></AuthProvider></ThemeProvider>; }
